describe('Dropdown selection tests', () => {
    beforeEach(() => {
        cy.visit('https://the-internet.herokuapp.com/dropdown');
    });

    it('should show the disabled prompt initially', () => {
        cy.get('#dropdown').should('have.value', '');
        cy.get('#dropdown option:first').should('have.text', 'Please select an option');
    });

    it('should select Option 2 and verify the selection', () => {
        cy.get('#dropdown').select('Option 2');
        cy.get('#dropdown').should('have.value', '2');
        cy.get('#dropdown option:selected').should('have.text', 'Option 2');
    });

    it('should not allow selection of an option when the dropdown is not interacted with', () => {
        cy.get('#dropdown').should('have.value', '');
        cy.get('#dropdown option:selected').should('have.text', 'Please select an option');
    });
});
